export type M3LResultOk<T> = { ok: true; value: T };
export type M3LResultErr<E> = { ok: false; error: E };
export type M3LResult<T, E = Error> = M3LResultOk<T> | M3LResultErr<E>;

export class M3LError extends Error {
  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = 'M3LError';
  }
}

export class M3LNotFoundError extends M3LError {}

/** Resolved paths used by the M3L execution environment. */
export interface M3LPaths {
  /** Directory where run archives are stored (renamed from outputDir). */
  archiveDir: string;
  workDir: string;
  logsDir: string;
}

export interface RetryOptions {
  maxAttempts?: number;
  baseDelayMs?: number;
}

export async function retry<T>(fn: () => Promise<T>, options?: RetryOptions): Promise<T> {
  throw new Error('not implemented');
}
